#!/usr/bin/env node
/**
 * National Library of Norway (Nasjonalbiblioteket) map harvest — sourcing swarm
 * 2026-10-20, member 1.
 *
 * Discovery uses the National Library's documented Catalog Search API:
 *
 *   https://api.nb.no/catalog/v1/items?q=*&size=100&page=<n>
 *     &filter=mediatype:kart&filter=publicdomain
 *
 * `mediatype:kart` is the library's own map media type; the second filter asks
 * the API for items whose own `accessInfo` declares `license: publicdomain`
 * (the response also carries `isPublicDomain: true` and `viewability: ALL`).
 * Every admitted item is therefore a real digitised map that the rights holder
 * has itself placed in the public domain. Items with `ccbync`, `copyrighted`,
 * `bokhylla` or no digital object are withheld and counted by reason.
 *
 * Rights evidence, kept per record:
 *   - API `accessInfo.license = "publicdomain"`, `isPublicDomain = true`
 *   - IIIF manifest `license = "https://www.nb.no/lisens/#public-domain"`
 *   - https://www.nb.no/tilgang/lisens/ — the library's licence page: material
 *     marked Public Domain may be copied, modified, distributed, displayed and
 *     performed, including commercially, without asking permission. The page
 *     also warns that rights may persist outside Norway; that territorial limit
 *     stays on every record rather than being flattened into a worldwide claim.
 *
 * Metadata reuse is a separate question from the image licence. This harvester
 * reproduces only the factual catalogue fields the API returns (title, creator,
 * publisher, issued date, language, place and identifiers) plus the library's
 * own links. It does not copy the library's descriptive notes. The admitted
 * object is itself declared public domain by the rights holder, and the same
 * item-level declaration is recorded as the reproduction basis, with
 * attribution and the original URN on every record. See
 * coordination/metadata-rights-nb-20261020.md for the recorded decision.
 *
 * No georeferencing is invented: the search API exposes no machine-readable map
 * extent, so records carry no `extent`, `geo` or `georeference`. The IIIF image
 * service is the first canvas of the digitised object and is labelled as such.
 *
 * Usage:
 *   node scripts/harvest-nb.mjs                 # cached harvest, writes public/data
 *   node scripts/harvest-nb.mjs --refresh       # refetch every API page
 *   node scripts/harvest-nb.mjs --no-write      # report only
 *   node scripts/harvest-nb.mjs --verify 24     # live verification sample size
 *   node scripts/harvest-nb.mjs --max-pages 2   # bounded slice for a smoke run
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readCore, shardPath, shardUrl, writeShard } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};

const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/nb');
const REFRESH = has('refresh');
const WRITE = !has('no-write') && !has('dry-run');
const VERIFY_SAMPLE = Math.max(0, Number(value('verify', '24')) || 0);
const MAX_PAGES = Math.max(1, Number(value('max-pages', '0')) || 0);
const PAGE_SIZE = 100;
const API = 'https://api.nb.no/catalog/v1/items';
const RETRIEVED = '2026-10-20';
const SHARD = shardUrl('nb');
const LICENCE = 'https://www.nb.no/lisens/#public-domain';
const LICENCE_PAGE = 'https://www.nb.no/tilgang/lisens/';
const INSTITUTION = 'Nasjonalbiblioteket (National Library of Norway)';
const UA =
  'maps-n-stuff/0.3 (+https://github.com/igor-makarov/maps-n-stuff; National Library of Norway map harvest)';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Documented discovery query: the library's own map media type + PD declaration. */
export function searchUrl(page) {
  const params = new URLSearchParams({ q: '*', size: String(PAGE_SIZE), page: String(page) });
  params.append('filter', 'mediatype:kart');
  params.append('filter', 'publicdomain');
  return `${API}?${params}`;
}

async function fetchText(url, { retries = 4 } = {}) {
  let last = null;
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    if (attempt > 0) await sleep(Math.min(16000, 1500 * 2 ** (attempt - 1)));
    let res;
    try {
      res = await fetch(url, {
        headers: { 'user-agent': UA, accept: 'application/json, text/html, image/jpeg, */*' },
        signal: AbortSignal.timeout(60000),
      });
    } catch (err) {
      last = err;
      continue;
    }
    if (res.status === 429 || res.status >= 500) {
      last = new Error(`${url}: HTTP ${res.status}`);
      const retryAfter = Number(res.headers.get('retry-after'));
      if (Number.isFinite(retryAfter) && retryAfter > 0) await sleep(Math.min(60000, retryAfter * 1000));
      continue;
    }
    if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
    return { body: Buffer.from(await res.arrayBuffer()), type: res.headers.get('content-type') ?? '' };
  }
  throw last ?? new Error(`${url}: request failed`);
}

async function getJson(url, opts) {
  const { body, type } = await fetchText(url, opts);
  try {
    return JSON.parse(body.toString('utf8'));
  } catch {
    throw new Error(`${url}: expected JSON, got ${type || 'unknown content type'}`);
  }
}

/** A cached page is only trusted when it is a successful items page. */
function validItemsPage(doc) {
  return (
    doc &&
    typeof doc === 'object' &&
    Array.isArray(doc._embedded?.items) &&
    Number.isFinite(doc.page?.totalElements) &&
    Number.isFinite(doc.page?.totalPages)
  );
}

async function cachedPage(page) {
  const file = resolve(CACHE, `page-${page}.json`);
  if (!REFRESH) {
    try {
      const doc = JSON.parse(await readFile(file, 'utf8'));
      if (validItemsPage(doc)) return doc;
    } catch {
      /* fetch below */
    }
  }
  const doc = await getJson(searchUrl(page));
  if (!validItemsPage(doc)) throw new Error(`${searchUrl(page)}: malformed items page`);
  if (WRITE) {
    await mkdir(CACHE, { recursive: true });
    await writeFile(file, `${JSON.stringify(doc)}\n`);
  }
  return doc;
}

const compact = (text) => String(text ?? '').replace(/\s+/g, ' ').trim();
const uniq = (values) => [...new Set(values.map(compact).filter(Boolean))];

const RIGHTS_REASONS = {
  licence: 'rights: item accessInfo.license is not "publicdomain"',
  publicDomain: 'rights: accessInfo.isPublicDomain is not true',
  viewability: 'rights: accessInfo.viewability is not ALL',
  digital: 'not a digitised object (accessInfo.isDigital is not true)',
  urn: 'no digitised map URN (URN:NBN:no-nb_digikart_…)',
  manifest: 'no IIIF presentation manifest link',
  thumbnail: 'no library thumbnail link',
  title: 'no title in the catalogue record',
};

/**
 * Gate an API item. Returns null when it may be admitted, otherwise the
 * withheld reason. The public-domain declaration is the item's own, never a
 * site-wide assumption; none of the checks is inferred from age or host.
 */
export function admission(item) {
  const access = item?.accessInfo ?? {};
  if (access.license !== 'publicdomain') return RIGHTS_REASONS.licence;
  if (access.isPublicDomain !== true) return RIGHTS_REASONS.publicDomain;
  if (access.viewability !== 'ALL') return RIGHTS_REASONS.viewability;
  if (access.isDigital !== true) return RIGHTS_REASONS.digital;
  const urn = item?.metadata?.identifiers?.urn;
  if (typeof urn !== 'string' || !/^URN:NBN:no-nb_digikart_/.test(urn)) return RIGHTS_REASONS.urn;
  if (!item?._links?.presentation?.href) return RIGHTS_REASONS.manifest;
  if (!item?._links?.thumbnail_large?.href) return RIGHTS_REASONS.thumbnail;
  if (!compact(item?.metadata?.title)) return RIGHTS_REASONS.title;
  return null;
}

/** Publication years stated by the catalogue; never the digitisation year. */
export function issuedYears(value) {
  const years = [...String(value ?? '').matchAll(/(?<!\d)(1[4-9]\d{2}|20\d{2})(?!\d)/g)].map((m) => Number(m[1]));
  if (!years.length) return null;
  const start = Math.min(...years);
  const end = Math.max(...years);
  if (start < 1400 || end > 2100) return null;
  return { start, end };
}

const normalizeApiUrl = (url) => String(url ?? '').replace('https://api.nb.no:443', 'https://api.nb.no');

/** Build the catalogue record from one admitted API item. Pure and testable. */
export function recordFromItem(item) {
  const reason = admission(item);
  if (reason) throw new Error(`${item?.id ?? '?'}: ${reason}`);
  const metadata = item.metadata;
  const links = item._links;
  const urn = metadata.identifiers.urn;
  const pageUrn = `${urn}_0001_F_01`;
  const years = issuedYears(metadata.originInfo?.issued);
  const languages = uniq((metadata.languages ?? []).map((language) => language?.code));
  const creators = uniq(metadata.creators ?? []);
  const place = compact(metadata.geographic?.placeString || metadata.geographic?.city) || null;
  const publisher = compact(metadata.originInfo?.publisher) || null;
  const pageCount = Number(metadata.pageCount);
  const record = {
    id: `nb:${item.id}`,
    title: compact(metadata.title),
    creators,
    providerId: 'nb',
    institution: INSTITUTION,
    collection: 'Nettbiblioteket – kart',
    originalCollection: 'digikart',
    rights: 'Public Domain (Nasjonalbiblioteket item declaration)',
    rightsBasis: 'publicdomain',
    rightsUrl: LICENCE,
    rightsPolicyUrl: LICENCE_PAGE,
    rightsNote:
      'The item is declared public domain by the National Library of Norway (accessInfo.license=publicdomain, isPublicDomain=true; IIIF manifest license https://www.nb.no/lisens/#public-domain). The library notes that rights may persist in jurisdictions other than Norway. This records the item-level declaration, not a worldwide legal claim.',
    attribution: `${INSTITUTION}, ${urn} (Public Domain)`,
    recordUrl: `https://www.nb.no/items/${item.id}`,
    iiifManifest: normalizeApiUrl(links.presentation.href),
    imageService: `https://www.nb.no/services/image/resolver/${pageUrn}`,
    thumbnail: `https://www.nb.no/services/image/resolver/${pageUrn}/full/0,400/0/native.jpg`,
    imageNote:
      'The preview and IIIF image service are the first digitised canvas of the object. Multi-page works keep the library’s stated page count; no page was dropped or reordered.',
    urn,
    type: 'map',
    languages,
    retrieved: RETRIEVED,
    metadataSource: normalizeApiUrl(links.mods?.href),
    geoNote:
      'Nasjonalbiblioteket publishes no machine-readable map extent for this item in the documented catalog API; no place pin, bounding box, overlay or image transform is inferred.',
  };
  if (years) {
    record.yearStart = years.start;
    record.yearEnd = years.end;
  }
  if (place) record.place = place;
  if (publisher) record.publisher = publisher;
  if (metadata.identifiers.oaiId) record.oaiId = compact(metadata.identifiers.oaiId);
  if (Number.isFinite(pageCount) && pageCount > 0) record.pageCount = pageCount;
  return record;
}

function sampleFor(records, count) {
  if (!records.length || count <= 0) return [];
  const sorted = [...records].sort((a, b) => a.id.localeCompare(b.id));
  const step = Math.max(1, Math.floor(sorted.length / count));
  const out = [];
  for (let i = 0; i < sorted.length && out.length < count; i += step) out.push(sorted[i]);
  return out;
}

/** Live evidence: manifest, its image service info.json, thumbnail bytes, record page. */
async function verify(records) {
  const sample = sampleFor(records, VERIFY_SAMPLE);
  const checks = {
    retrieved: RETRIEVED,
    sample: sample.length,
    manifestOk: 0,
    imageInfoOk: 0,
    thumbnailOk: 0,
    recordPageOk: 0,
    failures: [],
    examples: [],
  };
  for (const record of sample) {
    const result = { id: record.id, manifest: 0, imageInfo: 0, thumbnail: 0, recordPage: 0 };
    try {
      const manifest = await getJson(record.iiifManifest);
      result.manifest = 200;
      if (!compact(manifest.label)) throw new Error('manifest has no label');
      if (!/public-domain/i.test(String(manifest.license ?? ''))) throw new Error('manifest has no public-domain licence');
      const service = manifest.sequences?.[0]?.canvases?.[0]?.images?.[0]?.resource?.service?.['@id'];
      if (!service) throw new Error('manifest has no image service');
      checks.manifestOk += 1;
      await sleep(250);
      const info = await getJson(`${service}/info.json`);
      if (!(Number(info.width) > 0 && Number(info.height) > 0)) throw new Error('image info has no dimensions');
      result.imageInfo = 200;
      checks.imageInfoOk += 1;
      await sleep(250);
      const thumb = await fetchText(record.thumbnail);
      if (!thumb.body.subarray(0, 3).equals(Buffer.from([0xff, 0xd8, 0xff])))
        throw new Error(`thumbnail is not JPEG (${thumb.type})`);
      result.thumbnail = 200;
      checks.thumbnailOk += 1;
      await sleep(250);
      const page = await fetchText(record.recordUrl);
      if (!/text\/html/i.test(page.type)) throw new Error(`record page content type ${page.type}`);
      result.recordPage = 200;
      checks.recordPageOk += 1;
      if (checks.examples.length < 3) checks.examples.push(result);
    } catch (err) {
      checks.failures.push({ id: record.id, error: String(err.message ?? err).slice(0, 240), ...result });
      // A challenge or rate limit is a signal to stop sampling, not hammer on.
      if (/HTTP (?:403|429)/.test(String(err.message ?? err))) break;
    }
  }
  checks.note =
    'Live checks on the sampled records: IIIF manifest parses with a public-domain licence, its first canvas image service info.json has dimensions, the library thumbnail is real JPEG bytes, and the original record page answers text/html. The sample is evidence about the sample, not a claim that all records were opened; failures are kept verbatim.';
  return checks;
}

async function main() {
  const first = await cachedPage(0);
  const totalPages = Math.min(first.page.totalPages, MAX_PAGES || first.page.totalPages);
  const upstreamTotal = first.page.totalElements;
  const items = [];
  const pages = [];
  for (let page = 0; page < totalPages; page += 1) {
    const doc = page === 0 ? first : await cachedPage(page);
    pages.push({ page, items: doc._embedded.items.length, totalElements: doc.page.totalElements });
    items.push(...doc._embedded.items);
    if (WRITE) await sleep(200);
  }
  console.log(`Fetched ${pages.length} pages, ${items.length} candidate items (upstream total ${upstreamTotal}).`);

  const withheld = {};
  const records = [];
  const seen = new Set();
  for (const item of items) {
    const reason = admission(item);
    if (reason) {
      withheld[reason] = (withheld[reason] ?? 0) + 1;
      continue;
    }
    const record = recordFromItem(item);
    if (seen.has(record.id)) continue;
    seen.add(record.id);
    records.push(record);
  }
  records.sort((a, b) => (a.yearStart ?? 9999) - (b.yearStart ?? 9999) || a.id.localeCompare(b.id));

  const languages = {};
  for (const record of records) for (const code of record.languages) languages[code] = (languages[code] ?? 0) + 1;
  const years = records.flatMap((record) => [record.yearStart, record.yearEnd]).filter(Number.isFinite);
  const verification = await verify(records);
  console.log('Verification:', JSON.stringify(verification).slice(0, 800));

  const generatedAt = new Date().toISOString();
  const selection = {
    source: 'National Library of Norway — Nettbiblioteket maps (digikart)',
    endpoint: searchUrl(0),
    filter: ['mediatype:kart', 'publicdomain'],
    reportedByApi: upstreamTotal,
    pagesFetched: pages.length,
    considered: items.length,
    kept: records.length,
    withheld,
    shard: SHARD,
    rightsBasis: { publicdomain: records.length },
    languageCounts: languages,
    yearRange: years.length ? { start: Math.min(...years), end: Math.max(...years) } : null,
    undated: records.filter((record) => !Number.isFinite(record.yearStart)).length,
    multiPage: records.filter((record) => (record.pageCount ?? 0) > 2).length,
    policy: {
      url: LICENCE_PAGE,
      licence: LICENCE,
      statement:
        'The library’s licence page states that material marked Public Domain may be copied, modified, distributed, displayed and performed, including for commercial purposes, without permission, and warns that rights may persist in other jurisdictions. Every admitted item carries the library’s own public-domain declaration.',
      metadataReuse:
        'Only factual catalogue fields returned by the documented Catalog Search API are reproduced (title, creator, publisher, issued date, language, place, identifiers, page count) with the library’s original links and URN; NB-authored descriptive notes are not copied. The item-level public-domain declaration, attribution and URN are retained on every record. Recorded decision: coordination/metadata-rights-nb-20261020.md.',
    },
    rule:
      'Every map media type item with the API’s publicdomain filter is a candidate. It is admitted only when its own accessInfo declares license=publicdomain, isPublicDomain=true, viewability=ALL and isDigital=true, carries a digitised map URN, a IIIF manifest, a library thumbnail and a title. Undated items remain eligible and are not assigned a year. No extent, place pin, overlay, alignment or depicted date is inferred from age, title or footprint.',
    verification,
  };

  const shardDoc = {
    generatedAt,
    retrieved: RETRIEVED,
    providerId: 'nb',
    method:
      'Documented National Library of Norway Catalog Search API, mediatype:kart filtered to items whose own accessInfo declares publicdomain; IIIF presentation manifests and the library image resolver are the original image route.',
    selection,
    records,
  };

  const provider = {
    id: 'nb',
    name: 'National Library of Norway — Nettbiblioteket maps',
    operator: 'Nasjonalbiblioteket (National Library of Norway)',
    homepage: 'https://www.nb.no/',
    institutions: [INSTITUTION],
    rights:
      'Every bundled item is declared public domain by the National Library of Norway (accessInfo.license=publicdomain, isPublicDomain=true, viewability=ALL) and its IIIF manifest links https://www.nb.no/lisens/#public-domain. The library notes that rights may persist outside Norway. Items whose own record says ccbync, copyrighted or restricted are not imported.',
    rightsUrl: LICENCE,
    rightsPolicyUrl: LICENCE_PAGE,
    attribution: INSTITUTION,
    retrieved: RETRIEVED,
    mode: 'bundled',
    api: {
      catalogue: API,
      manifest: 'https://api.nb.no/catalog/v1/iiif/{id}/manifest',
      metadata: 'https://api.nb.no/catalog/v1/metadata/{id}/mods',
      image: 'https://www.nb.no/services/image/resolver/{urn}/full/full/0/native.jpg',
      documentation: 'https://api.nb.no/',
    },
    apiHosts: ['api.nb.no', 'www.nb.no', 'urn.nb.no'],
    method:
      'Documented Catalog Search API pagination (q=*, size=100, filter=mediatype:kart and filter=publicdomain). Every admitted record keeps its original title, creators, publisher, stated publication date, language, place and identifiers plus its IIIF manifest, image service, thumbnail, record page and URN. No bbox or alignment is inferred.',
    collections: [
      {
        id: 'digikart',
        name: 'Nettbiblioteket maps (digikart)',
        discovery: `${searchUrl(0)}&page=<n>`,
      },
    ],
    rightsPolicy: {
      licence: LICENCE,
      page: LICENCE_PAGE,
      territorialNote:
        'The library’s page states that it is not certain that all rights have expired in jurisdictions other than Norway. Records keep this caveat; no worldwide public-domain claim is made.',
      metadataReuse: {
        status: 'item-level-public-domain',
        basis:
          'Each admitted item is itself declared public domain by the rights holder in the documented API and in its own IIIF manifest (license link), and only factual catalogue fields returned by that API are reproduced with attribution, URN and original links. The library’s authored descriptive notes are omitted. Primary evidence: https://www.nb.no/tilgang/lisens/ and the per-item manifest license https://www.nb.no/lisens/#public-domain.',
        evidence: LICENCE_PAGE,
        decisionNote: 'coordination/metadata-rights-nb-20261020.md',
      },
    },
    verification,
  };

  const shardBytes = Buffer.byteLength(JSON.stringify(shardDoc));
  console.log(`NB shard ${(shardBytes / 1048576).toFixed(2)} MiB (${records.length} records)`);
  if (shardBytes > 24 * 1048576) throw new Error('NB shard exceeds 24 MiB; split it before writing.');
  if (!WRITE) {
    console.log('No-write run; public/data unchanged.');
    return;
  }

  const core = await readCore(OUT);
  const previous = core.selection?.['nb:digikart'];
  if (previous?.verification?.sample && verification.sample === 0) selection.verification = previous.verification;
  core.shards = [...new Set([...(core.shards ?? []), SHARD])].sort();
  core.records = (core.records ?? []).filter((record) => record.providerId !== 'nb');
  core.generatedAt = generatedAt;
  core.retrieved = RETRIEVED;
  core.selection ??= {};
  core.selection['nb:digikart'] = selection;
  core.method =
    core.method && core.method.includes('National Library of Norway')
      ? core.method
      : `${core.method ? `${core.method} ` : ''}National Library of Norway Nettbiblioteket maps are imported from the documented Catalog Search API with the library’s own public-domain declaration; they are bundled in ${SHARD}.`;

  const sourcesDoc = JSON.parse(await readFile(resolve(OUT, 'sources.json'), 'utf8'));
  sourcesDoc.providers = [...sourcesDoc.providers.filter((source) => source.id !== 'nb'), provider];
  sourcesDoc.generatedAt = generatedAt;

  await writeShard(OUT, SHARD, records, {
    generatedAt,
    retrieved: RETRIEVED,
    providerId: 'nb',
    method: shardDoc.method,
    selection,
  });
  await writeFile(resolve(OUT, 'records.json'), `${JSON.stringify(core, null, 2)}\n`);
