/**
 * National Library of Norway (nb) harvest regressions — sourcing member 1,
 * 2026-10-20.
 *
 * The fixture is a trimmed real Catalog Search API item (public-domain map,
 * digital `digikart` URN). The tests pin the rights gate, the factual-field
 * mapping and the "no invented extent/alignment" rule; they never contact the
 * network.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { admission, issuedYears, recordFromItem, searchUrl } from '../scripts/harvest-nb.mjs';

const item = {
  id: '6c4899668859d9db589777a7b5d4629e',
  _links: {
    self: { href: 'https://api.nb.no:443/catalog/v1/items/6c4899668859d9db589777a7b5d4629e' },
    mods: {
      href: 'https://api.nb.no:443/catalog/v1/metadata/6c4899668859d9db589777a7b5d4629e/mods',
    },
    presentation: {
      href: 'https://api.nb.no:443/catalog/v1/iiif/6c4899668859d9db589777a7b5d4629e/manifest',
    },
    thumbnail_large: {
      href: 'https://www.nb.no/services/image/resolver/URN:NBN:no-nb_digikart_gaa0010000776_0001_F_01/full/0,200/0/native.jpg',
    },
  },
  accessInfo: {
    accessAllowedFrom: 'EVERYWHERE',
    isDigital: true,
    isPublicDomain: true,
    license: 'publicdomain',
    viewability: 'ALL',
  },
  metadata: {
    creators: ['Lea, Philip'],
    geographic: { placeString: 'Storbritannia - London' },
    identifiers: {
      sesamId: '6c4899668859d9db589777a7b5d4629e',
      urn: 'URN:NBN:no-nb_digikart_gaa0010000776',
      oaiId: 'oai:nb.bibsys.no:999919992094602202',
    },
    languages: [{ code: 'eng' }],
    mediaTypes: ['kart'],
    originInfo: {
      publisher: 'By Philip Lea at the Atlas and Hercules in Cheapside, London',
      issued: '1685',
    },
    pageCount: 2,
    title:
      'A  New Map of Scandinavia, or the Northern Kingdoms of Swedland, Denmark, and Norway, &c divided into their General & Particular Parts',
  },
};

const clone = (value) => structuredClone(value);

test('the documented discovery query asks for the map media type and public domain only', () => {
  const url = new URL(searchUrl(0));
  assert.equal(url.origin + url.pathname, 'https://api.nb.no/catalog/v1/items');
  assert.equal(url.searchParams.get('q'), '*');
  assert.equal(url.searchParams.get('size'), '100');
  assert.equal(url.searchParams.get('page'), '0');
  assert.deepEqual(url.searchParams.getAll('filter'), ['mediatype:kart', 'publicdomain']);
});

test('an item carrying its own public-domain declaration is admitted', () => {
  assert.equal(admission(item), null);
});

test('items without the item-level public-domain declaration are withheld', () => {
  for (const [patch, expected] of [
    [{ license: 'ccbync' }, /license/],
    [{ isPublicDomain: false }, /isPublicDomain/],
    [{ viewability: 'NONE' }, /viewability/],
    [{ isDigital: false }, /digitised/],
  ]) {
    const candidate = clone(item);
    Object.assign(candidate.accessInfo, patch);
    assert.match(admission(candidate), expected);
  }
  const noUrn = clone(item);
  noUrn.metadata.identifiers.urn = 'URN:NBN:no-nb_digibok_2019010728005';
  assert.match(admission(noUrn), /book/i, 'a book-format digitisation is not a digikart sheet');
  const noManifest = clone(item);
  delete noManifest._links.presentation;
  assert.match(admission(noManifest), /manifest/);
  const noThumb = clone(item);
  delete noThumb._links.thumbnail_large;
  assert.match(admission(noThumb), /thumbnail/);
  const noTitle = clone(item);
  noTitle.metadata.title = '   ';
  assert.match(admission(noTitle), /title/);
});

test('records keep the archival title, creators, date, language, publisher and identifiers', () => {
  const record = recordFromItem(item);
  assert.equal(record.id, 'nb:6c4899668859d9db589777a7b5d4629e');
  assert.equal(record.title, item.metadata.title, 'title is preserved verbatim, double space included');
  assert.deepEqual(record.creators, ['Lea, Philip']);
  assert.deepEqual(record.languages, ['eng']);
  assert.equal(record.publisher, item.metadata.originInfo.publisher);
  assert.equal(record.place, 'Storbritannia - London');
  assert.equal(record.yearStart, 1685);
  assert.equal(record.yearEnd, 1685);
  assert.equal(record.urn, 'URN:NBN:no-nb_digikart_gaa0010000776');
  assert.equal(record.oaiId, 'oai:nb.bibsys.no:999919992094602202');
  assert.equal(record.recordUrl, 'https://www.nb.no/items/6c4899668859d9db589777a7b5d4629e');
  assert.equal(record.pageCount, 2);
  assert.equal(record.providerId, 'nb');
  assert.equal(record.type, 'map');
  assert.equal(record.rightsBasis, 'publicdomain');
  assert.match(record.rights, /Public Domain/);
  assert.match(record.attribution, /Nasjonalbiblioteket.*URN:NBN:no-nb_digikart_gaa0010000776/);
});

test('the image route is the documented IIIF manifest and first-canvas service', () => {
  const record = recordFromItem(item);
  assert.equal(
    record.iiifManifest,
    'https://api.nb.no/catalog/v1/iiif/6c4899668859d9db589777a7b5d4629e/manifest',
  );
  assert.equal(
    record.imageService,
    'https://www.nb.no/services/image/resolver/URN:NBN:no-nb_digikart_gaa0010000776_0001_F_01',
  );
  assert.match(record.thumbnail, /\/full\/0,400\/0\/native\.jpg$/);
  assert.equal(record.georeference, undefined);
  assert.equal(record.extent, undefined);
  assert.equal(record.geo, undefined);
  assert.equal(record.overlay, undefined);
  assert.match(record.geoNote, /no machine-readable map extent/i);
});

test('undated items stay eligible and are never assigned an invented year', () => {
  const undated = clone(item);
  undated.metadata.originInfo.issued = '';
  assert.equal(admission(undated), null);
  const record = recordFromItem(undated);
  assert.equal(record.yearStart, undefined);
  assert.equal(record.yearEnd, undefined);
  assert.equal(record.depictedYearStart, undefined);
  assert.equal(record.depictedYearEnd, undefined);
});

test('publication years come from the issued statement, including ranges and doubt marks', () => {
  assert.deepEqual(issuedYears('1685'), { start: 1685, end: 1685 });
  assert.deepEqual(issuedYears('[1685?]'), { start: 1685, end: 1685 });
  assert.deepEqual(issuedYears('1850-1860'), { start: 1850, end: 1860 });
  assert.deepEqual(issuedYears('ca. 1700'), { start: 1700, end: 1700 });
  assert.equal(issuedYears(''), null);
  assert.equal(issuedYears('udatert'), null);
  assert.equal(issuedYears('17--'), null);
});

test('the digitisation placeholder publisher is not presented as a real imprint', () => {
  const placeholder = clone(item);
  placeholder.metadata.originInfo.publisher = '[utgiver ikke identifisert]';
  assert.equal(recordFromItem(placeholder).publisher, undefined);
});

