test('mergeRecords preserves published records byte-for-byte and adds only new ids', () => {
  const published = [
    { id: 'nb:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', title: 'Published title', yearStart: 1600, yearEnd: 1600 },
    { id: 'nb:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', title: 'Another published map' },
  ];
  const rebuilt = [
    { id: 'nb:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', title: 'A rebuilt title that must not win', yearStart: 1601 },
    { id: 'nb:cccccccccccccccccccccccccccccccc', title: 'New undated map' },
  ];
  const merged = mergeRecords(published, rebuilt);
  assert.equal(merged.preserved, 1);
  assert.equal(merged.records.length, 3);
  assert.equal(merged.records[0].title, 'Published title', 'the published record is not rewritten');
  assert.equal(merged.records.filter((record) => record.id.endsWith('b')).length, 1, 'duplicates are impossible');
  assert.equal(merged.records.filter((record) => record.id.endsWith('c')).length, 1);
  assert.deepEqual(
    merged.records.map((record) => record.id),
    [...merged.records.map((record) => record.id)].sort(),
    'merged shard stays sorted by id',
  );
  const again = mergeRecords(merged.records, rebuilt);
  assert.equal(again.records.length, 3, 'a repeated run is idempotent');
  assert.equal(again.preserved, 2);
});

test('the no-year sweep extended the shard beyond the 1500–1945 windows', async () => {
  const shard = await readJson('public/data/records/nb.json');
  const catalogue = await readJson('public/data/records.json');
  const selection = catalogue.selection['nb:kart'];
  const records = shard.records;
  const years = records.map((record) => record.yearStart).filter(Number.isFinite);
  assert.equal(records.length, 2513, 'the complete public-domain map set');
  assert.equal(selection.kept, 2513);
  assert.equal(selection.publicDomainSweep.pages, 26);
  assert.equal(selection.publicDomainSweep.considered, 2513);
  assert.equal(selection.publicDomainSweep.added, 288, 'the sweep contribution over the dated windows');
  assert.equal(selection.windows.reduce((sum, window) => sum + window.kept, 0), 2225, 'published dated slice');
  assert.ok(years.some((year) => year < 1500), 'pre-1500 maps are retained');
  assert.ok(years.some((year) => year > 1945), 'post-1945 maps are retained');
  assert.ok(records.some((record) => record.yearStart === undefined), 'undated maps stay eligible');
  const pre1500 = records.find((record) => record.yearStart === 1482);
  assert.ok(pre1500 && pre1500.rightsBasis === 'publicdomain' && !pre1500.extent && !pre1500.georeference);
  const post1945 = records.find((record) => Number.isFinite(record.yearStart) && record.yearStart >= 1950);
  assert.ok(post1945 && post1945.rightsBasis === 'publicdomain' && !post1945.extent);
  const undated = records.find((record) => record.yearStart === undefined);
  assert.equal(undated.extent, undefined, 'an undated map does not gain an invented extent');
  assert.equal(undated.depictedYearStart, undefined, 'an undated map does not gain a depicted date');
});
